sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.form = { nome: '', email: '', telefone: '', consentimentoLgpd: false };

    c.salvar = function() {
        c.erro = null;
        c.msg = null;
        if (!c.form.nome) {
            c.erro = "Campo 'nome' é obrigatório.";
            return;
        }
        if (!c.form.consentimentoLgpd) {
            c.erro = 'É obrigatório o aceite do termo LGPD.';
            return;
        }
        c.data.action = 'salvar';
        angular.extend(c.data, c.form);
        c.server.update().then(function(r) {
            if (r.data.sucesso) {
                c.msg = 'Cliente cadastrado com sucesso!';
                c.form = { nome: '', email: '', telefone: '', consentimentoLgpd: false };
            } else {
                c.erro = r.data.erro;
            }
        });
    };
};

sp_widget.script:
(function() {
    // Widget de intake: consentimento LGPD é obrigatório nesta tela (política de
    // recepção), mesmo a API/UseCase permitindo consentimentoLgpd=false para
    // outros fluxos de integração.
    if (input && input.action === 'salvar') {
        if (!input.consentimentoLgpd) {
            data.erro = 'É obrigatório o aceite do termo LGPD.';
            return;
        }
        try {
            var out = new CadastrarClienteUseCase().execute({
                nome: input.nome,
                email: input.email,
                telefone: input.telefone,
                consentimentoLgpd: true,
                consentimentoVersao: 'v1.0',
                consentimentoFinalidade: 'Prestação de serviços de depilação a laser e comunicação com o cliente'
            });
            data.sucesso = true;
            data.clienteId = out.sys_id;
        } catch (e) {
            data.erro = e.message || 'Não foi possível cadastrar o cliente.';
        }
    }
})();
